/* eslint-env jest */
'use strict';

const os = require('os');

const yandexLogger = require('../../src');

describe('YandexLogger. Middleware. Blackbox', () => {
    let logger;
    let stream;
    let jestFakeTimers;
    let baseRecord;

    beforeEach(() => {
        stream = { write: jest.fn() };

        logger = yandexLogger({
            streams: [
                { stream },
            ],
            middleware: [
                require('../../middleware/blackbox')(),
            ],
        });

        baseRecord = {
            pid: process.pid,
            date: expect.any(Date),
            name: 'yandex-logger',
            hostname: os.hostname(),
            level: 30,
            levelName: 'INFO',
            msg: 'message',
            msgFormat: 'message',
            msgArgs: [],
        };

        // Use fake timers and set the system time
        jestFakeTimers = jest.useFakeTimers('modern');
        jest.setSystemTime(1000);
    });

    afterEach(() => {
        jestFakeTimers.clearAllTimers();
    });

    it('должен взять пользователя из req.blackbox', () => {
        let req = {
            requestId: 'req-1',
            blackbox: {
                uid: 'user-id',
                login: 'user-login',
                email: 'user-email',
                avatar: 'user-avatar',
            },
        };
        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            user: {
                uid: 'user-id',
            },
            req: {
                requestId: 'req-1',
                blackbox: {
                    uid: 'user-id',
                    login: 'user-login',
                    email: 'user-email',
                    avatar: 'user-avatar',
                },
            },
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('не должен брать пользователя без uid', () => {
        let req = {
            requestId: 'req-1',
            blackbox: {
                login: 'user-login',
            },
        };
        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req: {
                requestId: 'req-1',
                blackbox: {
                    login: 'user-login',
                },
            },
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('не должен падать без req.blackbox', () => {
        let req = {};
        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req,
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('не должен падать без record.req', () => {
        logger.info('message');

        expect(stream.write).toHaveBeenCalledWith(baseRecord);
        expect(stream.write).toHaveBeenCalledTimes(1);
    });
});
